tmail.com", "outlook.com", "yahoo.com", "icloud.com", "proton.me"]};

const elegir = (obj) => {
    const claves = Object.keys(obj);
    const total = claves.reduce((s, k) => s + obj[k], 0);
    let r = Math.random() * total;
    for (const k of claves) { r -= obj[k]; if (r <= 0) return k; }
    return claves[claves.length - 1];
};
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
const randInt = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const norm = (t) => t.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

// Pool de identidades (se crea una vez y se reutiliza -> usuarios recurrentes)
let pool = context.get('pool');
if (!pool || !pool[0] || !pool[0].fabricante) {   // se recrea si el pool es de una versión anterior
    pool = [];
    for (let i = 0; i < 3000; i++) {
        const nombre = pick(D.NOMBRES), apellido = pick(D.APELLIDOS);
        const so = elegir(D.SISTEMAS);
        const fab = elegir(D.FAB_POR_OS[so]);        // fabricante coherente con el SO (como en el CSV v3)
        pool.push({
            fabricante: fab,
            nombre: nombre + ' ' + apellido,
            email: norm(nombre) + '.' + norm(apellido).replace(/ /g, '') + '@' + pick(D.DOMINIOS),
            edad: randInt(15, 85),
            pais: elegir(D.PAISES),
            os: so,
            idioma: elegir(D.IDIOMAS[so])
        });
    }
    context.set('pool', pool);
}

// Más tráfico en las horas punta (7:30-9:30 y 18:00-20:00, hora de Madrid)
const p = new Intl.DateTimeFormat('en-GB', {timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit', hour12: false}).format(new Date()).split(':');
const minutos = parseInt(p[0]) * 60 + parseInt(p[1]);
const punta = (minutos >= 450 && minutos <= 570) || (minutos >= 1080 && minutos <= 1200);
const n = punta ? randInt(2, 4) : randInt(0, 1);

const ahora = Date.now();
const registros = [];
for (let i = 0; i < n; i++) {
    const per = pick(pool);
    const marca = per.fabricante;
    const mac = pick(D.FABRICANTES[marca].prefijos) + ':' +
        [0, 1, 2].map(() => randInt(0, 255).toString(16).toUpperCase().padStart(2, '0')).join(':');
    const r = {
        hora_ms: ahora + i,           // +i ms para que no coincidan dos puntos
        mac: mac, fabricante: marca, nombre: per.nombre, os: per.os,
        idioma: per.idioma, edad: String(per.edad), email: per.email, pais: per.pais
    };
    // ~3% de registros con errores, como en el CSV (se descartarán al validar)
    if (Math.random() < 0.03) {
        const t = randInt(1, 5);
        if (t === 1) r.mac = 'MAC-INVALIDA';
        if (t === 2) r.email = r.email.replace('@', '');
        if (t === 3) r.pais = 'ESP';
        if (t === 4) r.edad = 'edad_' + r.edad;
