// Simulador de compras en el aeropuerto (misma lógica que generador_indices.py)
// Un "tick" dura 3 s: las probabilidades por minuto del .py se reparten entre los 20 ticks de cada minuto.
const TICKS_POR_MINUTO = 20;

const TIENDAS_SOUVENIR = [
    { nombre: "Budget Treasures",  gama: "budget",    precio: [2, 15] },
    { nombre: "Island Keepsakes",  gama: "mid-range", precio: [15, 60] },
    { nombre: "Luxury Souvenirs",  gama: "premium",   precio: [60, 250] }
];
const TIENDAS_VIAJE = [
    { nombre: "Travel Essentials",   precio: [5, 40] },
    { nombre: "Wanderlust Supplies", precio: [8, 55] }
];
const CAFETERIAS = [
    { nombre: "Bean There Café",  precio: [3, 8] },
    { nombre: "Morning Brew",     precio: [3, 9] },
    { nombre: "Caffeine Corner",  precio: [2, 7] },
    { nombre: "The Daily Grind",  precio: [4, 10] },
    { nombre: "Espresso Express", precio: [3, 8] }
];

const randInt = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const uniforme = (a, b) => a + Math.random() * (b - a);
const redondea = (x) => Math.round(x * 100) / 100;

// Hora de Madrid
const p = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit', hour12: false })
    .format(new Date()).split(':');
const hora = parseInt(p[0]);
const minutos = hora * 60 + parseInt(p[1]);
const cafeteriasAbiertas = hora >= 8 && hora <= 20;                                   // 08:00-21:00
const horaPunta = (minutos >= 450 && minutos <= 570) || (minutos >= 960 && minutos <= 1200);   // 7:30-9:30 y 16:00-20:00

const tiendas = [];
TIENDAS_SOUVENIR.forEach(t => tiendas.push({ tipo: "souvenir", ...t }));
TIENDAS_VIAJE.forEach(t => tiendas.push({ tipo: "travel_necessity", ...t }));
if (cafeteriasAbiertas) CAFETERIAS.forEach(t => tiendas.push({ tipo: "coffee", ...t }));

let id = context.get('transaction_id') || 1000;
const ahora = Date.now();
const puntos = [];
for (const t of tiendas) {
    let n = 0;
    if (horaPunta) { if (Math.random() < 0.80 / TICKS_POR_MINUTO) n = randInt(1, 3); }   // punta: 1-3 compras
    else           { if (Math.random() < 0.30 / TICKS_POR_MINUTO) n = 1; }               // normal: 0-1 compras
    for (let k = 0; k < n; k++) {
        const precioUnidad = redondea(uniforme(t.precio[0], t.precio[1]));
        const unidades = randInt(1, 5);
        const tags = { shop_name: t.nombre, shop_type: t.tipo };
        if (t.gama) tags.price_bracket = t.gama;
        puntos.push({
            measurement: 'ventas',
            tags: tags,
            fields: { transaction_id: id, items_sold: unidades, unit_price: precioUnidad, total_revenue: redondea(precioUnidad * unidades) },
            timestamp: ahora + puntos.length          // +1 ms por compra para que no coincidan
        });
        id++;
    }
}
context.set('transaction_id', id);
if (puntos.length === 0) return null;
msg.payload = puntos;
return msg;

// Transporte HTTP a InfluxDB (sustituye al nodo influxdb batch).
// Convierte [{measurement, tags, fields, timestamp_ms}] a line protocol
// y deja la peticion lista con env.get (entorno del proceso).
function esc(s){return String(s).replace(/,/g,'\\,').replace(/ /g,'\\ ').replace(/=/g,'\\=');}
function fieldVal(v){
  if(typeof v==='boolean') return v?'t':'f';
  if(typeof v==='number') return Number.isInteger(v)? v+'i' : String(v);
  return '"'+String(v).replace(/\\/g,'\\\\').replace(/"/g,'\\"')+'"';
}
const pts = Array.isArray(msg.payload)?msg.payload:[msg.payload];
const lines = pts.map(p=>{
  const tags = Object.entries(p.tags||{}).map(([k,v])=>esc(k)+'='+esc(v)).join(',');
  const fields = Object.entries(p.fields||{}).map(([k,v])=>esc(k)+'='+fieldVal(v)).join(',');
  let line = p.measurement+','+tags+' '+fields;
  if(p.timestamp) line += ' '+p.timestamp;
  return line;
}).filter(l=>l.indexOf(' ')>0);
if(!lines.length) return null;
msg.payload = lines.join('\n');
msg.url = env.get('INFLUXDB_URL')+'/api/v2/write?org='+env.get('INFLUXDB_ORG')+'&bucket=captaciones_tiemporeal&precision=ms';
msg.headers = {Authorization: 'Token '+env.get('INFLUXDB_TOKEN'), 'Content-Type': 'text/plain; charset=utf-8'};
return msg;

